/**
 * Export the HappyDomLocator class for instanceof checks
 */
export { HappyDomLocator }

/**
 * Wrapper around @testing-library/user-event that provides API compatibility
 * with vitest/browser's userEvent (which has `fill` instead of `type`).
 */
export const userEvent = {
  ...testingLibraryUserEvent,
  /**
   * Fill an input element with text. Clears existing content first.
   * Maps to testing-library's clear() + type() since it doesn't have fill().
   */
  async fill(element: Element, text: string): Promise<void> {
    await user.clear(element)
    await user.type(element, text)
  },
}

import { fileURLToPath, URL } from 'node:url'
import tailwindcss from '@tailwindcss/vite'
import vue from '@vitejs/plugin-vue'
import { playwright } from '@vitest/browser-playwright'
import { configDefaults, defineConfig } from 'vitest/config'
import { VitePWA } from 'vite-plugin-pwa'

// Shared resolve config for path aliases
const resolve = {
  alias: {
    '@': fileURLToPath(new URL('src', import.meta.url)),
  },
}

// Pre-bundle dependencies to avoid Vite reloads during browser tests
const optimizeDeps = {
  include: ['workbox-window'],
}

// Shared plugins for all projects
const plugins = [vue(), tailwindcss(), VitePWA({ devOptions: { enabled: true } })]

// Shared base configuration for all projects
// All tests run in Playwright browser mode for consistent, real-browser behavior
const sharedTestConfig = {
  root: fileURLToPath(new URL('./', import.meta.url)),
  exclude: [...configDefaults.exclude, 'e2e/**'],
  // Run test files in parallel - resetDatabase() resets all singleton state
  fileParallelism: true,
  // Stop test execution after first failure
  bail: 1,
  // Required for ArchUnitTS custom matchers
  globals: true,
  browser: {
    enabled: true,
    provider: playwright(),
    instances: [{ browser: 'chromium' as const }],
    headless: true,
  },
  setupFiles: ['./src/__tests__/setup.ts'],
}

// Note: This file is excluded from tsconfig.vitest.json type checking due to plugin type conflicts
export default defineConfig({
  plugins,
  resolve,
  optimizeDeps,
  test: {
    ...sharedTestConfig,

    // Filter out noisy WakeLock errors in browser tests
    onConsoleLog(log: string, type: 'stdout' | 'stderr'): false | void {
      if (type === 'stderr' && log.includes('[WakeLock]')) {
        return false // Suppress all WakeLock warnings (expected in test environment)
      }
      // Let all other messages through
    },

    // Coverage configuration (applies to default project when using --coverage)
    coverage: {
      provider: 'v8',
      reporter: ['text'],
      include: ['src/**/*.{ts,vue}'],
      exclude: ['src/**/*.d.ts', 'src/__tests__/**', 'src/components/ui/**'],
      thresholds: {
        lines: 80,
        functions: 80,
        branches: 75,
        statements: 80,
      },
    },

    // Project-based configuration for running different test suites
    projects: [
      // Project 1: Default (browser mode - main tests)
      {
        plugins,
        resolve,
        optimizeDeps,
        test: {
          ...sharedTestConfig,
          name: 'default',
          include: ['src/__tests__/**/*.spec.ts', '!src/__tests__/a11y/**', '!src/__tests__/visual/**'],
        },
      },

      // Project 2: Happy-DOM (fast local testing for integration tests)
      {
        plugins,
        resolve,
        optimizeDeps,
        test: {
          root: fileURLToPath(new URL('./', import.meta.url)),
          name: 'happy-dom',
          environment: 'happy-dom',
          include: ['src/__tests__/integration/**/*.spec.ts'],
          exclude: [...configDefaults.exclude, '**/*.browser.spec.ts'],
          globals: true,
          setupFiles: ['./src/__tests__/setup.happy-dom.ts'],
        },
      },

      // Project 3: Accessibility tests
      {
        plugins,
        resolve,
        optimizeDeps,
        test: {
          ...sharedTestConfig,
          name: 'a11y',
          include: ['src/__tests__/a11y/**/*.spec.ts'],
        },
      },

      // Project 4: Visual regression tests
      {
        plugins,
        resolve,
        optimizeDeps,
        test: {
          ...sharedTestConfig,
          name: 'visual',
          include: ['src/__tests__/visual/**/*.spec.ts'],
          browser: {
            enabled: true,
            provider: playwright(),
            instances: [{ browser: 'chromium' as const }],
            headless: true,
            expect: {
              toMatchScreenshot: {
                comparatorOptions: {
                  threshold: 0.2,
                  allowedMismatchedPixelRatio: 0.02,
                },
              },
            },
          },
        },
      },

      // Project 5: Architecture tests (ArchUnitTS)
      // Runs in Node.js (not browser) for filesystem analysis
      {
        resolve,
        test: {
          name: 'arch',
          globals: true,
          include: ['src/__tests__/architecture/**/*.test.ts'],
          // No browser config - runs in Node for filesystem access
        },
      },
    ],
  },
})
